const config = $input.first().json;
const rawTarget = String(config.targetUrl || '').trim();
const objective = String(config.objective || '').trim();

if (!rawTarget) throw new Error('targetUrl is required');
if (!objective) throw new Error('objective is required');
if (objective.length > 500) throw new Error('objective must be 500 characters or fewer');

let target;
try {
  target = new URL(rawTarget);
} catch {
  throw new Error('targetUrl must be a valid public HTTP or HTTPS URL');
}
if (!['http:', 'https:'].includes(target.protocol)) {
  throw new Error('targetUrl must use HTTP or HTTPS');
}
const hostname = target.hostname.toLowerCase();
const privateHost = hostname === 'localhost'
  || hostname.endsWith('.local')
  || hostname === '0.0.0.0'
  || hostname === '127.0.0.1'
  || hostname === '::1'
  || /^10\./.test(hostname)
  || /^192\.168\./.test(hostname)
  || /^169\.254\./.test(hostname)
  || /^172\.(1[6-9]|2\d|3[01])\./.test(hostname);
if (privateHost) throw new Error('targetUrl must resolve to a public host');

return [{ json: { targetUrl: target.toString(), objective } }];

const report = $input.first().json;
const readiness = report.readiness && typeof report.readiness === 'object' ? report.readiness : {};
const pack = report.acceptance_pack && typeof report.acceptance_pack === 'object' ? report.acceptance_pack : {};
const gate = pack.launch_gate && typeof pack.launch_gate === 'object' ? pack.launch_gate : {};
const score = Number(readiness.score || 0);
const riskFlags = Array.isArray(readiness.risk_flags) ? readiness.risk_flags : [];
const acceptanceTests = Array.isArray(pack.acceptance_tests) ? pack.acceptance_tests : [];
const backlog = Array.isArray(pack.prioritized_backlog) ? pack.prioritized_backlog : [];
const requiresAttention = gate.decision !== 'ready' || score < 80 || riskFlags.length > 0;

return [{ json: {
  targetUrl: report.target?.final_url || report.target?.requested_url || null,
  objective: pack.objective || null,
  readinessScore: score,
  readinessGrade: readiness.grade || null,
  launchDecision: gate.decision || 'unknown',
  riskFlags,
  acceptanceTestCount: acceptanceTests.length,
  backlogCount: backlog.length,
  requiresAttention,
  acceptancePack: pack,
  evidence: {
    target: report.target || null,
    page: report.page || null,
    security: report.security_headers || null,
    readiness
  }
} }];
